-- Tabla de tallas oficial de TAUPOC (R-Skin Jammer y R-Skin Knee Suit).
-- La tabla cargada al inicio tenía medidas y equivalencias que no
-- correspondían a la oficial. Se corrigen las filas de cada producto según
-- su género; la estatura es la del talle chino (3XS/120 = 120 cm).
UPDATE "SizeChartRow" r SET "chestMinCm" = NULL, "chestMaxCm" = NULL, "waistMinCm" = 50, "waistMaxCm" = 55, "hipMinCm" = NULL, "hipMaxCm" = NULL, "heightMinCm" = 120, "heightMaxCm" = NULL, "cn" = '3XS/120', "usa" = '20', "uk" = '20', "aus" = '6', "nz" = 'B4' FROM "Product" p WHERE p.id = r."productId" AND p.gender = 'MALE' AND r.size = '20';
UPDATE "SizeChartRow" r SET "chestMinCm" = 55, "chestMaxCm" = 60, "waistMinCm" = 50, "waistMaxCm" = 55, "hipMinCm" = 55, "hipMaxCm" = 60, "heightMinCm" = 120, "heightMaxCm" = NULL, "cn" = '3XS/120', "usa" = '20', "uk" = '20', "aus" = 'G6', "nz" = 'G4' FROM "Product" p WHERE p.id = r."productId" AND p.gender = 'FEMALE' AND r.size = '20';
UPDATE "SizeChartRow" r SET "chestMinCm" = NULL, "chestMaxCm" = NULL, "waistMinCm" = 55, "waistMaxCm" = 60, "hipMinCm" = NULL, "hipMaxCm" = NULL, "heightMinCm" = 130, "heightMaxCm" = NULL, "cn" = '2XS/130', "usa" = '22', "uk" = '22', "aus" = '8', "nz" = 'B6' FROM "Product" p WHERE p.id = r."productId" AND p.gender = 'MALE' AND r.size = '22';
